#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Mise en ligne de J1 (#79) : rattrapage local, vérifications, push du rattrapage, fusion de #80, nouveau
# déclencheur du cron, premier import quotidien et interface. Rien n'est poussé ni fusionné sans un « y » à la question.
#
#   scripts/mise-en-ligne-j1.sh           toutes les étapes, depuis la première
#   scripts/mise-en-ligne-j1.sh 4         reprendre à l'étape 4 (après un rattrapage déjà fait, par exemple)
#   scripts/mise-en-ligne-j1.sh liste     la liste des étapes
#
# Variables : DONNEES (clone du dépôt de données, par défaut à côté de ce dépôt), TRAVAIL (journaux, listes à relire
# et notes de la relecture, hors des deux dépôts).

ETAPES=(
  "prealables|Préalables : branche j1/conseils, outils, PR #80"
  "clone|Clone du dépôt de données à côté du dépôt"
  "rattrapage|Rattrapage local sans push (plusieurs heures)"
  "comptes|Vérification : Objets et Séances contre OpenParlData"
  "tailles|Vérification : taille des fichiers de lecture"
  "masquage|Vérification : titres de pétitions masqués"
  "douteux|Vérification : cas douteux du jeu annoté"
  "echantillon|Vérification : échantillon de rattachements et corrections.json"
  "second_import|Vérification : un second import ne change rien"
  "pousser|Pousser le rattrapage"
  "fusion|Fusionner la PR #80 et publier le site"
  "declencheur|Remplacer le déclencheur du cron du dépôt de données"
  "premier_import|Suivre le premier import quotidien, la sonde et import-conseils"
  "interface|Vérifier l'interface en ligne"
  "bilan|Bilan et commentaire sur #79"
)
TOTAL_STAGES=${#ETAPES[@]}

DEPOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PIPELINE="$DEPOT/pipeline"
DONNEES="${DONNEES:-$(dirname "$DEPOT")/vigie-vaud-donnees}"
TRAVAIL="${TRAVAIL:-${XDG_STATE_HOME:-$HOME/.local/state}/vigie-vaud/mise-en-ligne-j1}"
NOTES="$TRAVAIL/notes.md"
ENV_FILE="$TRAVAIL/valeurs.env"   # `ask` y cherche ses valeurs par défaut ; rien n'y est écrit
BRANCHE=j1/conseils
PR=80
TICKET=79
REPO_CODE=Louni-M/vigie-vaud
REPO_DONNEES=Louni-M/vigie-vaud-donnees
SITE=https://louni-m.github.io/vigie-vaud
PAGES_DONNEES=https://louni-m.github.io/vigie-vaud-donnees
mkdir -p "$TRAVAIL"

# ── Outils des étapes ─────────────────────────────────────────────────────

# lancer CMD… affiche la commande, puis la lance.
lancer() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
# gd ARGS… : git dans le clone du dépôt de données.
gd() { git -C "$DONNEES" "$@"; }
# py ARGS… <<'PY' : Python du pipeline (httpx, pydantic, modules du cron), lancé depuis `pipeline/`.
py() { (cd "$PIPELINE" && uv run --quiet python - "$@"); }
# voir FICHIER : une longue liste à relire, dans le pager.
voir() { if [[ -t 1 ]]; then less -R -F -X "$1"; else cat "$1"; fi; }
arreter() { printf '\n'; warn "$1"; note "Reprendre avec : scripts/mise-en-ligne-j1.sh $_STAGE_INDEX"; exit 1; }
noter() { printf -- '- %s · %s\n' "$(date '+%F %R')" "$1" >> "$NOTES"; }
# valider "question" : y, ou bien une remarque notée pour la suite.
valider() {
  if confirm "$1"; then
    noter "OK · $1"
  else
    ask REMARQUE "Ce qui ne va pas (noté dans $NOTES) :"
    noter "À REPRENDRE · $1 · ${REMARQUE:-sans précision}"
    warn "noté ; à reprendre avant d'aller plus loin si c'est bloquant"
  fi
}
suite() { printf '\n'; pause "Entrée : étape suivante"; }
# depot_propre : le clone du dépôt de données n'a aucun changement en cours.
depot_propre() { [[ -z "$(gd status --porcelain)" ]]; }
# lancer_long FICHIER_JOURNAL CMD… : une commande de plusieurs heures, machine tenue éveillée, journal gardé.
lancer_long() {
  local journal="$1"; shift
  local cafe=()
  command -v caffeinate >/dev/null 2>&1 && cafe=(caffeinate -ims)
  note "Journal : $journal"
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  local debut=$SECONDS
  if ! (cd "$PIPELINE" && ${cafe[@]+"${cafe[@]}"} "$@") 2>&1 | tee "$journal"; then
    arreter "la commande a échoué : voir $journal"
  fi
  printf '\n  %s✓ terminé en %d min%s\n' "$GREEN" $(((SECONDS - debut) / 60)) "$RESET"
}
# echecs_du_journal FICHIER : les imports en échec et les pannes affichés par le passage.
echecs_du_journal() {
  if grep -E "^(Import en échec|Panne)" "$1"; then
    warn "le passage a signalé des échecs (ci-dessus)"
    return 1
  fi
  printf '  %s✓ aucun import en échec, aucune panne%s\n' "$GREEN" "$RESET"
}

# ── 1 ─────────────────────────────────────────────────────────────────────
etape_prealables() {
  say "Le rattrapage tourne avec le code de J1 : il faut la branche $BRANCHE, à jour et propre."
  local manque=0 outil
  for outil in git gh uv curl python3 less; do
    command -v "$outil" >/dev/null 2>&1 || { warn "$outil introuvable"; manque=1; }
  done
  (( manque == 0 )) || arreter "installer les outils manquants"
  gh auth status >/dev/null 2>&1 || arreter "gh n'est pas connecté : gh auth login"
  command -v caffeinate >/dev/null 2>&1 || warn "caffeinate absent : empêcher la mise en veille à la main pendant le rattrapage"

  local branche; branche=$(git -C "$DEPOT" rev-parse --abbrev-ref HEAD)
  [[ "$branche" == "$BRANCHE" ]] || arreter "le dépôt est sur $branche : git switch $BRANCHE"
  lancer git -C "$DEPOT" fetch --quiet origin
  if [[ -n "$(git -C "$DEPOT" status --porcelain --untracked-files=no)" ]]; then
    warn "changements en cours dans $DEPOT (le rattrapage tournera avec eux) :"
    git -C "$DEPOT" status --short --untracked-files=no
  fi
  if [[ "$(git -C "$DEPOT" rev-parse HEAD)" != "$(git -C "$DEPOT" rev-parse "origin/$BRANCHE")" ]]; then
    warn "$BRANCHE diffère de origin/$BRANCHE :"
    git -C "$DEPOT" log --oneline --left-right "HEAD...origin/$BRANCHE" | head -n 10
  else
    printf '  %s✓ %s à jour (%s)%s\n' "$GREEN" "$BRANCHE" "$(git -C "$DEPOT" log -1 --format=%h)" "$RESET"
  fi

  say ""
  say "PR #$PR :"
  gh pr view "$PR" -R "$REPO_CODE" --json state,mergeStateStatus,title \
    -q '"  \(.state) · \(.mergeStateStatus) · \(.title[0:70])…"'
  gh pr checks "$PR" -R "$REPO_CODE" 2>/dev/null | sed 's/^/  /' || true

  say ""
  if gh api "repos/$REPO_DONNEES/contents/conseils/import.json" >/dev/null 2>&1; then
    warn "conseils/import.json existe déjà sur $REPO_DONNEES : un rattrapage y a déjà été poussé"
  else
    printf '  %s✓ aucun rattrapage encore poussé sur %s%s\n' "$GREEN" "$REPO_DONNEES" "$RESET"
  fi
  local etat_pr; etat_pr=$(gh pr view "$PR" -R "$REPO_CODE" --json state -q .state)
  [[ "$etat_pr" == "OPEN" ]] || warn "la PR #$PR est $etat_pr : le rattrapage devait être poussé AVANT sa fusion"

  say ""
  lancer uv sync --quiet --project "$PIPELINE"
  note "Notes de la relecture : $NOTES"
  suite
}

# ── 2 ─────────────────────────────────────────────────────────────────────
etape_clone() {
  say "Le rattrapage s'écrit dans un clone du dépôt de données : $DONNEES"
  if [[ -d "$DONNEES/.git" ]]; then
    printf '  %s✓ clone présent%s\n' "$GREEN" "$RESET"
    gd remote get-url origin | grep -q "vigie-vaud-donnees" || arreter "$DONNEES n'est pas un clone de $REPO_DONNEES"
    [[ "$(gd rev-parse --abbrev-ref HEAD)" == "main" ]] || arreter "le clone n'est pas sur main"
    depot_propre || { gd status --short; arreter "le clone a des changements en cours"; }
    lancer gd fetch --quiet origin
    if [[ -n "$(gd log --oneline origin/main..HEAD)" ]]; then
      warn "commits locaux non poussés (un rattrapage déjà fait ?) :"
      gd log --oneline origin/main..HEAD | head -n 10
      note "S'ils sont un rattrapage complet, reprendre plutôt à l'étape 4 : scripts/mise-en-ligne-j1.sh 4"
    else
      lancer gd pull --ff-only --quiet
    fi
  else
    lancer git clone "https://github.com/$REPO_DONNEES.git" "$DONNEES"
  fi
  say ""
  gd log -3 --format='  %h %s'
  [[ -f "$DONNEES/conseils/import.json" ]] && warn "conseils/import.json existe déjà dans le clone"
  suite
}

# ── 3 ─────────────────────────────────────────────────────────────────────
etape_rattrapage() {
  say "Le passage du cron, avec --rattrapage et sans push : sondes, puis import de tout l'historique des trois"
  say "conseils, à une requête par seconde, et un commit dans le clone. Il télécharge environ 340 Mo de texte"
  say "des documents du Grand Conseil (pour le rattachement, jamais conservé) : compter plusieurs heures."
  step "Laisser ce terminal ouvert et la machine branchée (caffeinate la garde éveillée)."
  step "Si la session coupe : le clone garde ce qui est écrit ; refaire cette étape (scripts/mise-en-ligne-j1.sh 3)."
  say ""
  note "Commande du ticket : cd pipeline && uv run python cron.py --depot ../../vigie-vaud-donnees --sans-push --rattrapage"
  [[ "$(git -C "$DEPOT" rev-parse --abbrev-ref HEAD)" == "$BRANCHE" ]] || arreter "le dépôt n'est plus sur $BRANCHE"
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  if ! confirm "Lancer le rattrapage maintenant ?"; then
    warn "rattrapage non lancé ; les vérifications suivantes en ont besoin"
    suite; return
  fi
  local avant; avant=$(gd rev-parse HEAD)
  lancer_long "$TRAVAIL/rattrapage-1.log" uv run python cron.py --depot "$DONNEES" --sans-push --rattrapage
  printf '%s\n' "$avant" > "$TRAVAIL/avant-rattrapage"
  say ""
  echecs_du_journal "$TRAVAIL/rattrapage-1.log" || true
  grep -E " : [0-9]+ Objet\(s\), [0-9]+ Séance\(s\) lus" "$TRAVAIL/rattrapage-1.log" | sed 's/^/  /' || true
  say ""
  say "Dernier import réussi de chaque conseil (conseils/import.json) :"
  py "$DONNEES" <<'PY'
import json, sys
from pathlib import Path
from schema import RACINE, lire_sources
depot = Path(sys.argv[1])
imports = json.loads((depot / "conseils/import.json").read_text())["conseils"]
for s in lire_sources(RACINE / "sources.json").sources:
    if s.conseil:
        print(f"  {s.conseil.cle:>5}  {imports.get(s.conseil.cle, '⚠ ABSENT : import en échec')}  {s.nom_court}")
PY
  say ""
  gd log -1 --format='  Commit %h « %s »'
  gd show --stat --format= HEAD | tail -n 1 | sed 's/^/ /'
  noter "Rattrapage local : $(gd log -1 --format='%h %s'), journal $TRAVAIL/rattrapage-1.log"
  suite
}

# ── 4 ─────────────────────────────────────────────────────────────────────
etape_comptes() {
  say "Fichiers de l'archive par conseil, contre les totaux d'OpenParlData (requêtes à 1 par seconde)."
  py "$DONNEES" "$TRAVAIL/comptes.txt" <<'PY'
import sys, time
from pathlib import Path
import httpx
from conseils import API, TYPES_ECARTES, USER_AGENT
from schema import RACINE, lire_sources

depot = Path(sys.argv[1])

def total(entite, **params):
    time.sleep(1)
    r = httpx.get(f"{API}/{entite}/", params={**params, "limit": "1", "fields": "id", "client": "vigie-vaud"},
                  headers={"User-Agent": USER_AGENT}, timeout=60)
    r.raise_for_status()
    return r.json()["meta"]["total_records"]

ligne = "  {:<30} {:>8} {:>10} {:>8} {:>7}"
lignes = [ligne.format("", "archive", "OpenParl.", "écartés", "écart")]
for s in lire_sources(RACINE / "sources.json").sources:
    c = s.conseil
    if not c:
        continue
    if "objets" in c.donne:
        archive = len(list((depot / f"conseils/{c.cle}/objets").glob("*.json")))
        opd = total("affairs", body_key=c.body_key)
        ecartes = sum(total("affairs", body_key=c.body_key, type_name=t) for t in TYPES_ECARTES)
        lignes.append(ligne.format(f"{s.nom_court} · Objets", archive, opd, ecartes, archive - (opd - ecartes)))
    if "seances" in c.donne:
        archive = len(list((depot / f"conseils/{c.cle}/seances").glob("*.json")))
        params = {"body_key": c.body_key} | ({"group_id": str(c.groupe)} if c.groupe else {})
        opd = total("meetings", **params)
        lignes.append(ligne.format(f"{s.nom_court} · Séances", archive, opd, "", archive - opd))
print("\n".join(lignes))
Path(sys.argv[2]).write_text("\n".join(lignes) + "\n")
PY
  say ""
  note "Écarts attendus : Objets sans numéro écartés ; deux Objets au même numéro, ou deux Séances le même jour,"
  note "ne font qu'un fichier (la clé d'une Séance est son jour) ; changements chez OpenParlData depuis le rattrapage."
  note "Un écart positif (plus de fichiers que de lignes) ou un gros écart négatif est à comprendre avant de pousser."
  say ""
  noter "Nombres (archive, OpenParlData, écartés, écart) :"
  sed 's/^  /    /' "$TRAVAIL/comptes.txt" | tail -n +2 >> "$NOTES"
  valider "Les nombres concordent, ou leurs écarts s'expliquent ?"
  suite
}

# ── 5 ─────────────────────────────────────────────────────────────────────
etape_tailles() {
  say "Les fichiers de lecture sont ce que le site télécharge : taille brute et compressée (Pages sert en gzip)."
  py "$DONNEES" "$TRAVAIL/tailles.txt" <<'PY'
import gzip, sys
from pathlib import Path
from lecture_conseils import MOTIFS_LECTURE

depot, sortie = Path(sys.argv[1]), Path(sys.argv[2])
fichiers = sorted({f for m in MOTIFS_LECTURE for f in depot.glob(m)}, key=lambda f: -f.stat().st_size)
ko = lambda n: f"{n / 1024:,.0f} Ko".replace(",", " ")
lignes = [f"{ko(f.stat().st_size):>10} {ko(len(gzip.compress(f.read_bytes()))):>10} gz  {f.relative_to(depot)}"
          for f in fichiers]
archive = [f for f in (depot / "conseils").rglob("*.json")]
resume = [
    f"Fichiers de lecture : {len(fichiers)}, {ko(sum(f.stat().st_size for f in fichiers))} en tout",
    f"Dossier conseils/ : {len(archive)} fichiers, {ko(sum(f.stat().st_size for f in archive))}",
    *(f"{(depot / n).relative_to(depot)} : {ko((depot / n).stat().st_size)}"
      for n in ("conseils/index.json", "conseils/fil.json") if (depot / n).exists()),
]
sortie.write_text("\n".join(resume + ["", "Les plus gros :"] + lignes) + "\n")
print("\n".join("  " + l for l in resume + ["", "Les plus gros :"] + lignes[:15]))
PY
  say ""
  gd count-objects -vH | grep -E "size-pack" | sed 's/^/  Clone (.git) : /'
  note "Liste complète : $TRAVAIL/tailles.txt"
  noter "Tailles : $(head -n 2 "$TRAVAIL/tailles.txt" | tr '\n' ';' )"
