# ── 6 ─────────────────────────────────────────────────────────────────────
etape_masquage() {
  say "Tous les titres de pétitions masqués, avec leur lien chez la source pour comparer avec l'original."
  say "Ensuite, pour mémoire, les autres titres masqués et les pétitions non masquées."
  py "$DONNEES" "$TRAVAIL/masquage.txt" <<'PY'
import json, sys
from pathlib import Path
from masquage import MASQUE, TYPES_SANS_AUTEUR

depot, sortie = Path(sys.argv[1]), Path(sys.argv[2])
petitions_masquees, autres_masques, petitions_claires, points = [], [], [], []
for f in sorted(depot.glob("conseils/*/objets/*.json")):
    o = json.loads(f.read_text())
    cle = f"{f.parent.parent.name}/{f.stem}"
    ligne = f"{cle:<22} {o['titre']}\n{'':<22} {o.get('lien') or '(sans lien)'}"
    if o["type"] in TYPES_SANS_AUTEUR:
        (petitions_masquees if MASQUE in o["titre"] else petitions_claires).append(ligne)
    elif MASQUE in o["titre"]:
        autres_masques.append(f"[{o['type']}] {ligne}")
for f in sorted(depot.glob("conseils/*/seances/*.json")):
    s = json.loads(f.read_text())
    for p in s["ordre_du_jour"]:
        if MASQUE in p["titre"]:
            points.append(f"{f.parent.parent.name}/{f.stem}  {p['titre']}")
parties = [
    (f"PÉTITIONS AU TITRE MASQUÉ ({len(petitions_masquees)}) : à relire toutes", petitions_masquees),
    (f"AUTRES OBJETS AU TITRE MASQUÉ ({len(autres_masques)})", autres_masques),
    (f"POINTS D'ORDRE DU JOUR MASQUÉS ({len(points)})", points),
    (f"PÉTITIONS NON MASQUÉES ({len(petitions_claires)}) : un nom de particulier y aurait échappé ?", petitions_claires),
]
sortie.write_text("\n\n".join(t + "\n" + "=" * len(t) + "\n" + "\n".join(l) for t, l in parties) + "\n")
for t, l in parties:
    print("  " + t)
PY
  say ""
  step "Pour chaque titre masqué : plus aucun nom de particulier, et ni élu·e ni entité masqué·e à tort."
  step "Comparer au besoin avec le titre d'origine (lien sous chaque titre)."
  note "Liste : $TRAVAIL/masquage.txt (q pour sortir du pager)"
  pause "Entrée : ouvrir la liste"
  voir "$TRAVAIL/masquage.txt"
  valider "Les titres de pétitions masqués sont justes ?"
  suite
}

