etape_echantillon() {
  local graine; graine=$(date +%Y%m%d)
  say "Un échantillon tiré au hasard (graine $graine) des Objets du Grand Conseil : 40 avec des communes"
  say "rattachées (justes ?), puis 15 sans commune (une commune nommée aurait-elle échappé ?)."
  py "$DONNEES" "$TRAVAIL/echantillon.txt" "$graine" <<'PY'
import json, random, sys
from pathlib import Path
from rattachement import COMMUNES_JSON

depot, sortie, graine = Path(sys.argv[1]), Path(sys.argv[2]), int(sys.argv[3])
noms = {c["bfs"]: c["nom"] for c in json.loads(COMMUNES_JSON.read_text())}
objets = [(f"vd/{f.stem}", json.loads(f.read_text())) for f in sorted(depot.glob("conseils/vd/objets/*.json"))]
avec = [o for o in objets if o[1]["communes"]]
sans = [o for o in objets if not o[1]["communes"]]
hasard = random.Random(graine)
def bloc(cle, o):
    communes = ", ".join(f"{noms.get(c['ofs'], '?')} ({c['ofs']}, {c['origine']})" for c in o["communes"]) or "aucune"
    return f"{cle} · {o['type']} · {o['depose']}\n  {o['titre']}\n  → {communes}\n  {o.get('lien') or ''}"
parties = [
    (f"AVEC COMMUNES : 40 sur {len(avec)}", [bloc(*o) for o in hasard.sample(avec, min(40, len(avec)))]),
    (f"SANS COMMUNE : 15 sur {len(sans)}", [bloc(*o) for o in hasard.sample(sans, min(15, len(sans)))]),
]
sortie.write_text("\n\n".join(t + "\n" + "=" * len(t) + "\n\n" + "\n\n".join(l) for t, l in parties) + "\n")
print(f"  {len(objets)} Objets du Grand Conseil, dont {len(avec)} rattachés à au moins une commune")
PY
  note "Liste : $TRAVAIL/echantillon.txt"
  pause "Entrée : ouvrir la liste"
  voir "$TRAVAIL/echantillon.txt"
  say ""
  say "Une erreur se corrige dans corrections.json, à la racine du dépôt de données (ADR 0016) :"
  note '  [ { "objet": "vd/26_INT_140", "retirer": [5586], "ajouter": [], "note": "la raison" } ]'
  if ! confirm "Écrire ou compléter corrections.json maintenant ?"; then
    noter "Échantillon de rattachements (graine $graine) relu, sans correction"
    suite; return
  fi
  [[ -f "$DONNEES/corrections.json" ]] || printf '[]\n' > "$DONNEES/corrections.json"
  while true; do
    "${VISUAL:-${EDITOR:-nano}}" "$DONNEES/corrections.json"
    if py "$DONNEES" <<'PY'
import sys
from pathlib import Path
from rattachement import lire_corrections
print(f"  ✓ corrections.json valide : {len(lire_corrections(Path(sys.argv[1])))} Objet(s) corrigé(s)")
PY
    then break; fi
    confirm "corrections.json est invalide : le reprendre ?" || arreter "corrections.json invalide"
  done
  if [[ -z "$(gd status --porcelain -- corrections.json)" ]]; then
    noter "Échantillon de rattachements (graine $graine) relu, corrections.json inchangé"
    suite; return
  fi
  say ""
  say "Les corrections valent pour les Objets déjà archivés dès l'import suivant : un import court les applique"
  say "(changements du jour seulement, quelques requêtes), et reconstruit les fichiers de lecture."
  lancer_long "$TRAVAIL/corrections.log" uv run python conseils.py --depot "$DONNEES" --depuis "$(date +%F)"
  echecs_du_journal "$TRAVAIL/corrections.log" || true
  gd status --short | head -n 20
  if confirm "Committer corrections.json et les Objets corrigés (commit local, sans push) ?"; then
    lancer gd add -- corrections.json conseils
    lancer gd commit --quiet -m "Corrections de rattachement (relecture de la mise en ligne de J1)"
    noter "corrections.json : $(gd log -1 --format=%h), graine $graine"
  else
    warn "non committé : l'étape 10 attend un clone propre"
  fi
  suite
}

# ── 9 ─────────────────────────────────────────────────────────────────────
etape_second_import() {
  say "Un second import ne doit rien changer sous conseils/, hors conseils/import.json (réécrit à chaque passage,"
  say "comme etat-sources.json)."
  step "1 · second rattrapage complet, sans push (aussi long que le premier) : le contrôle du ticket"
  step "2 · import court des 7 derniers jours (conseils.py --depuis) : quelques minutes, contrôle partiel"
  step "3 · passer"
  local choix; printf '  %sChoix [1] :%s ' "$BOLD" "$RESET"; read -r choix || true
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  local avant; avant=$(gd rev-parse HEAD)
  case "${choix:-1}" in
    1)
      lancer_long "$TRAVAIL/rattrapage-2.log" uv run python cron.py --depot "$DONNEES" --sans-push --rattrapage
      echecs_du_journal "$TRAVAIL/rattrapage-2.log" || true
      gd diff --stat "$avant" HEAD -- conseils ':(exclude)conseils/import.json' > "$TRAVAIL/second-import.txt"
      ;;
    2)
      local depuis; depuis=$(py <<'PY'
from datetime import date, timedelta
print(date.today() - timedelta(days=7))
PY
)
      lancer_long "$TRAVAIL/import-court.log" uv run python conseils.py --depot "$DONNEES" --depuis "$depuis"
      echecs_du_journal "$TRAVAIL/import-court.log" || true
      gd add --intent-to-add -- conseils
      gd diff --stat -- conseils ':(exclude)conseils/import.json' > "$TRAVAIL/second-import.txt"
      ;;
    *) warn "second import passé"; noter "Second import : non fait"; suite; return ;;
  esac
  say ""
  if [[ -s "$TRAVAIL/second-import.txt" ]]; then
    warn "des fichiers ont changé sous conseils/ :"
    tail -n 20 "$TRAVAIL/second-import.txt" | sed 's/^/  /'
    note "Un Objet modifié chez OpenParlData entre les deux imports est normal ; un fichier réécrit sans raison"
    note "(ordre, genere, rattachement instable) ne l'est pas : ne pas pousser avant de comprendre."
    if [[ "${choix:-1}" == 1 ]]; then note "Détail : git -C $DONNEES diff $avant HEAD -- conseils"
    else note "Détail : git -C $DONNEES diff -- conseils"; fi
  else
    printf '  %s✓ rien n'"'"'a changé sous conseils/ hors import.json%s\n' "$GREEN" "$RESET"
  fi
  if [[ "${choix:-1}" == 2 ]]; then
    # L'import court ne committe pas : on rend le clone propre pour le push.
    gd reset --quiet -- conseils
    if [[ -s "$TRAVAIL/second-import.txt" ]]; then
      warn "les changements de l'import court restent dans le clone : les committer ou les annuler avant l'étape 10"
    else
      gd checkout -- conseils/import.json
    fi
  fi
  valider "Le second import ne change rien sous conseils/ (ou seulement des changements réels de la source) ?"
  suite
}

# ── 10 ────────────────────────────────────────────────────────────────────
etape_pousser() {
  say "Le rattrapage part sur main du dépôt de données, AVANT la fusion de #$PR : sinon le premier passage"
  say "planifié du code de J1 le refait lui-même, avec push. D'ici la fusion, les passages du code de J0 ne"
  say "touchent pas à conseils/ ; ils réécrivent etat-sources.json et schema/."
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  [[ -f "$DONNEES/conseils/import.json" ]] || arreter "pas de conseils/import.json dans le clone : le rattrapage manque"
  lancer gd fetch --quiet origin
  say ""
  say "À pousser :"
  gd log --format='  %h %s' origin/main..HEAD
  say "Arrivé entre-temps sur origin/main (passages du cron) :"
  gd log --format='  %h %s' HEAD..origin/main | head -n 5
  gd count-objects -vH | grep -E "size-pack" | sed 's/^/  Clone (.git) : /'
  say ""
  if [[ -n "$(gd log --oneline HEAD..origin/main)" ]]; then
    note "Les passages du cron ont réécrit etat-sources.json et schema/ : en cas de conflit, la version locale"
    note "(celle du code de J1) l'emporte (rebase -X theirs) ; le passage suivant les réécrit de toute façon."
    confirm "Rebaser le rattrapage sur origin/main ?" || { warn "rien n'est poussé"; suite; return; }
    if ! lancer gd rebase --quiet -X theirs origin/main; then
      gd rebase --abort || true
      arreter "le rebase a échoué ; rien n'est poussé"
    fi
    python3 -m json.tool "$DONNEES/etat-sources.json" >/dev/null || arreter "etat-sources.json invalide après le rebase"
  fi
  if ! confirm "Pousser $(gd rev-list --count origin/main..HEAD) commit(s) vers $REPO_DONNEES (main) ?"; then
    warn "rien n'est poussé"; suite; return
  fi
  until lancer gd push origin HEAD:main; do
    warn "push refusé : un passage du cron est sans doute arrivé entre-temps"
    confirm "Rebaser de nouveau sur origin/main et réessayer ?" || arreter "rattrapage non poussé"
    lancer gd fetch --quiet origin
    lancer gd rebase --quiet -X theirs origin/main || { gd rebase --abort || true; arreter "le rebase a échoué"; }
  done
  noter "Rattrapage poussé : $(gd log -1 --format=%h) sur $REPO_DONNEES"
  say ""
  note "Pages du dépôt de données se met à jour au prochain passage du cron (minutes 17 et 47, souvent plus tard)."
  open_url "https://github.com/$REPO_DONNEES/commits/main"
  suite
}

# ── 11 ────────────────────────────────────────────────────────────────────
etape_fusion() {
  say "Fusion de la PR #$PR dans main (commit de fusion, comme J0), puis publication du site : le workflow"
  say "« Publication du site » ne se lance qu'à la main. Jusqu'à l'étape suivante, l'ancien déclencheur du"
  say "dépôt de données appelle le code de J1 sans entrée : des passages ordinaires, sans rattrapage."
  say ""
  gh pr view "$PR" -R "$REPO_CODE" --json state,mergeable,mergeStateStatus \
    -q '"  \(.state) · mergeable \(.mergeable) · \(.mergeStateStatus)"'
  gh pr checks "$PR" -R "$REPO_CODE" 2>/dev/null | sed 's/^/  /' || true
  gh api "repos/$REPO_DONNEES/contents/conseils/import.json" >/dev/null 2>&1 \
    || warn "conseils/import.json est absent de $REPO_DONNEES : le rattrapage n'est pas poussé (étape 10)"
  say ""
  if [[ "$(gh pr view "$PR" -R "$REPO_CODE" --json state -q .state)" == "MERGED" ]]; then
    printf '  %s✓ PR #%s déjà fusionnée%s\n' "$GREEN" "$PR" "$RESET"
  elif confirm "Fusionner la PR #$PR dans main ?"; then
    lancer gh pr merge "$PR" -R "$REPO_CODE" --merge
    noter "PR #$PR fusionnée"
  else
    warn "PR non fusionnée"; suite; return
  fi
  say ""
  if confirm "Lancer « Publication du site » (publier.yml) sur main ?"; then
    lancer gh workflow run publier.yml -R "$REPO_CODE" --ref main
    sleep 5
    local id; id=$(gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 --json databaseId -q '.[0].databaseId')
    lancer gh run watch "$id" -R "$REPO_CODE" --exit-status || warn "la publication a échoué : gh run view $id -R $REPO_CODE --log-failed"
    noter "Site publié (run $id)"
  fi
  say ""
  gh run list -R "$REPO_CODE" --branch main -L 3 | sed 's/^/  /' || true
  suite
}

