etape_declencheur() {
  local modele="$PIPELINE/depot-donnees/.github/workflows/cron.yml"
  local cible="$DONNEES/.github/workflows/cron.yml"
  say "Le déclencheur du dépôt de données devient le modèle de J1 : entrée « rattrapage » du lancement manuel."
  say ""
  diff -u "$cible" "$modele" | sed 's/^/  /' || true
  say ""
  # Le nouveau déclencheur passe l'entrée « rattrapage » au workflow réutilisable de main : sans elle (avant la
  # fusion de #80), chaque passage planifié échouerait au démarrage.
  if ! gh api "repos/$REPO_CODE/contents/.github/workflows/cron.yml?ref=main" -q .content | base64 --decode \
      | grep -q "rattrapage:"; then
    arreter "le cron.yml de main ne déclare pas encore l'entrée « rattrapage » : fusionner #$PR d'abord (étape 11)"
  fi
  printf '  %s✓ le cron.yml de main déclare l'"'"'entrée « rattrapage »%s\n' "$GREEN" "$RESET"
  say ""
  if diff -q "$cible" "$modele" >/dev/null; then
    printf '  %s✓ déjà à jour%s\n' "$GREEN" "$RESET"; suite; return
  fi
  if ! confirm "Remplacer le déclencheur, committer et pousser vers $REPO_DONNEES ?"; then
    warn "déclencheur inchangé"; suite; return
  fi
  depot_propre || arreter "le clone a des changements en cours"
  lancer gd pull --rebase --quiet
  cp "$modele" "$cible"
  lancer gd add -- .github/workflows/cron.yml
  lancer gd commit --quiet -m "Déclencheur du cron : entrée « rattrapage » (J1, ADR 0015)"
  until lancer gd push origin HEAD:main; do
    confirm "Push refusé : rebaser et réessayer ?" || arreter "déclencheur non poussé"
    lancer gd pull --rebase --quiet
  done
  noter "Déclencheur du cron remplacé : $(gd log -1 --format=%h)"
  suite
}

